CREATE TABLE Favorite (id VARCHAR(191) NOT NULL PRIMARY KEY,userId VARCHAR(191) NOT NULL,productId VARCHAR(191) NOT NULL,createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY Favorite_userId_productId_key(userId,productId)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE SupportTicket (id VARCHAR(191) NOT NULL PRIMARY KEY,userId VARCHAR(191) NOT NULL,subject VARCHAR(191) NOT NULL,message TEXT NOT NULL,state VARCHAR(191) NOT NULL DEFAULT 'OPEN',reply TEXT NOT NULL,repliedBy VARCHAR(191) NULL,repliedAt DATETIME(3) NULL,createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX SupportTicket_userId_createdAt_idx(userId,createdAt)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
